        ('auth', N'{"seo.login.title":"Log in to thakurg.com","seo.login.desc":"Log in with your e-mail and password to open {page:khata} and the other thakurg.com apps. One account for every app.","seo.signup.title":"Create a free thakurg.com account","seo.signup.desc":"Sign up free with your e-mail address. Your account opens {page:khata} right away; an administrator can give access to more apps.","seo.profile.title":"Your profile","seo.profile.desc":"Your thakurg.com account: name, language, password and the apps you can open.","seo.noaccess.title":"No access to this app","seo.noaccess.desc":"Your account cannot open this app yet. Ask an administrator for access.","auth.login.h1":"Log in","auth.login.lead":"One account for every app on thakurg.com.","auth.login.btn":"Log in","auth.signup.h1":"Create your account","auth.signup.lead":"Sign up free with your e-mail address. {page:khata} is ready right away; other apps are opened by an administrator.","auth.signup.btn":"Create account","auth.name":"Your name","auth.email":"E-mail","auth.password":"Password","auth.pwHint":"At least 8 characters.","auth.show":"Show password","auth.hide":"Hide password","auth.busy":"Please wait…","auth.toSignup":"New here? Create an account","auth.toLogin":"Already have an account? Log in","auth.serverDown":"The server could not be reached. Please try again in a moment.","auth.menu":"Account menu of {name}","auth.loginLink":"Log in","auth.profile":"Profile","auth.master":"Settings","auth.logout":"Log out","auth.p.h1":"Your profile","auth.p.lead":"Logged in as {email}.","auth.p.signedOut":"Log in to see your profile.","auth.p.details":"Your details","auth.p.language":"Language","auth.p.save":"Save","auth.p.pw.h":"Change password","auth.p.pw.current":"Current password","auth.p.pw.new":"New password","auth.p.pw.btn":"Change password","auth.p.apps.h":"Your apps","auth.p.apps.none":"No apps yet.","auth.p.apps.note":"Other apps are opened by an administrator. Ask one if you need access.","aut