        ('nexon', N'{"nexon.h1":"Nexon audio player","nexon.lead":"Play the Nexon tracks right in your browser.","nexon.empty2":"Use the + button above the playlist to add audio files.","seo.nexon.title":"Nexon Audio Player: Play Music Online","seo.nexon.desc":"Nexon is a simple online audio player with a playlist, seek bar, volume, shuffle and repeat. Works on phone and desktop."}', N'{"nexon.h1":"नेक्सन ऑडियो प्लेयर","nexon.lead":"नेक्सन के गाने सीधे अपने ब्राउज़र में सुनें।","nexon.empty2":"ऑडियो फ़ाइलें जोड़ने के लिए प्लेलिस्ट के ऊपर + बटन दबाएं।","seo.nexon.title":"नेक्सन ऑडियो प्लेयर: ऑनलाइन संगीत सुनें","seo.nexon.desc":"नेक्सन प्लेलिस्ट, सीक बार, वॉल्यूम, शफ़ल और रिपीट वाला एक सरल ऑनलाइन ऑडियो प्लेयर है। फ़ोन और डेस्कटॉप पर चलता है।"}', N'{"nexon.h1":"مشغل نيكسون الصوتي","nexon.lead":"شغّل مقاطع نيكسون مباشرة في متصفحك.","nexon.empty2":"استخدم زر + فوق قائمة التشغيل لإضافة ملفات صوتية.","seo.nexon.title":"مشغل نيكسون الصوتي: استمع إلى الموسيقى عبر الإنترنت","seo.nexon.desc":"نيكسون مشغل صوتي بسيط عبر الإنترنت مع قائمة تشغيل وشريط تقديم وتحكم بالصوت وتشغيل عشوائي وتكرار. يعمل على الهاتف والحاسوب."}'),
        ('hr', N'{"seo.hr.title":"Atrium HR: Attendance, Leave and Payroll Software Demo","seo.hr.desc":"Atrium HR demo: manage employees, attendance, leave, payroll, hiring and reports in one place. Try the admin console and the employee mobile app.","hr.frame":"Atrium HR: sign in and workspace","hr.imgalt":"Atrium HR dashboard for attendance, leave and payroll","hr.h1":"Atrium HR: attendance, leave and payroll in one place","hr.p1":"Atrium is a demo HR workspace. Sign in above to open the admin console or the employee mobile app and try employees, attendance, leave, payroll, hiring and reports with sample data.","hr.h2.try":"What you can try","hr.f1.h":"Employees","hr.f1.p":"Profiles, departments, employment types and documents in one directory.","hr.f2.h":"Attendance","hr.f2.p":"Daily attendance, a monthly muster and employee check-in with a selfie and geofence.","hr.f3.h":"Leave","hr.f3.p":"Leave types, balances, requests and approvals with a clear policy.","hr.f4.h":"Payroll","hr.f4.p":"Monthly pay runs with basic pay, HRA, PF, ESI, professional tax and TDS, plus payslips.","hr.f5.h":"Hiring","hr.f5.p":"Job openings, a candidate pipeline, interviews with feedback, and offers with onboarding.","hr.f6.h":"Reports","hr.f6.p":"Attendance trends, headcount by department, hiring funnel and cost charts.","hr.h2.admin":"Admin console and employee app","hr.p2":"HR admins manage people, approve leave, run payroll and read reports in the console. Employees use a phone-sized app to check in with a selfie inside the office geofence, apply for leave and view payslips.","hr.h2.demo":"About the demo data","hr.p3":"Everything runs in your browser and uses sample data. Changes stay on your device. Do not enter real employee or payroll information.","hr.l.speed":"Internet speed test"}', N'{"seo.hr.title":"एट्रियम एचआर: उपस्थिति, छुट्टी और पेरोल सॉफ़्टवेयर डेमो","seo.hr.desc":"एट्रियम एचआर डेमो: कर्मचारी, उपस्थिति, छुट्टी, पेरोल, भर्ती और रिपोर्ट एक ही जगह संभालें। एडमिन कंसोल और कर्मचारी मोबाइल ऐप आज़माएं।","hr.frame":"एट्रियम एचआर: साइन इन और कार्यक्षेत्र","hr.imgalt":"उपस्थिति, छुट्टी और पेरोल के लिए एट्रियम एचआर डैशबोर्ड","hr.h1":"एट्रियम एचआर: उपस्थिति, छुट्टी और पेरोल एक ही जगह","hr.p1":"एट्रियम एक डेमो एचआर कार्यक्षेत्र है। ऊपर साइन इन करके एडमिन कंसोल या कर्मचारी मोबाइल ऐप खोलें और नमूना डेटा के साथ कर्मचारी, उपस्थिति, छुट्टी, पेरोल, भर्ती और रिपोर्ट आज़माएं।","hr.h2.try":"आप क्या आज़मा सकते हैं","hr.f1.h":"कर्मचारी","hr.f1.p":"प्रोफ़ाइल, विभाग, रोज़गार के प्रकार और दस्तावेज़ एक ही निर्देशिका में।","hr.f2.h":"उपस्थिति","hr.f2.p":"दैनिक उपस्थिति, मासिक मस्टर और सेल्फी व जियोफ़ेंस के साथ कर्मचारी चेक-इन।","hr.f3.h":"छुट्टी","hr.f3.p":"स्पष्ट नीति के साथ छुट्टी के प्रकार, शेष, अनुरोध और स्वीकृतियां।","hr.f4.h":"पेरोल","hr.f4.p":"मूल वेतन, एचआरए, पीएफ, ईएसआई, व्यावसायिक कर और टीडीएस के साथ मासिक पे रन, और पेस्लिप।","hr.f5.h":"भर्ती","hr.f5.p":"नौकरी के अवसर, उम्मीदवार पाइपलाइन, फ़ीडबैक के साथ साक्षात्कार, और ऑनबोर्डिंग के साथ ऑफ़र।","hr.f6.h":"रिपोर्ट","hr.f6.p":"उपस्थिति रुझान, विभाग के अनुसार कर्मचारी संख्या, भर्ती फ़नल और लागत चार्ट।","hr.h2.admin":"एडमिन कंसोल और कर्मचारी ऐप","hr.p2":"एचआर एडमिन कंसोल में लोगों का प्रबंधन करते हैं, छुट्टी स्वीकृत करते हैं, पेरोल चलाते हैं और रिपोर्ट देखते हैं। कर्मचारी फ़ोन के आकार के ऐप में ऑफ़िस जियोफ़ेंस के भीतर सेल्फी से चेक-इन करते हैं, छुट्टी के लिए आवेदन करते हैं और पेस्लिप देखते हैं।","hr.h2.demo":"डेमो डेटा के बारे में","hr.p3":"सब कुछ आपके ब्राउज़र में चलता है और नमूना डेटा का उपयोग करता है। बदलाव आपके डिवाइस पर ही रहते हैं। वास्तविक कर्मचारी या पेरोल जानकारी दर्ज न करें।","hr.l.speed":"इंटरनेट स्पीड टेस्ट"}', N'{"seo.hr.title":"أتريوم للموارد البشرية: نسخة تجريبية للحضور والإجازات والرواتب","seo.hr.desc":"نسخة أتريوم التجريبية: أدر الموظفين والحضور والإجازات والرواتب والتوظيف والتقارير في مكان واحد. جرّب وحدة الإدارة وتطبيق الموظف للجوال.","hr.frame":"أتريوم للموارد البشرية: تسجيل الدخول ومساحة العمل","hr.imgalt":"لوحة أتريوم للموارد البشرية للحضور والإجازات والرواتب","hr.h1":"أتريوم للموارد البشرية: الحضور والإجازات والرواتب في مكان واحد","hr.p1":"أتريوم مساحة عمل تجريبية للموارد البشرية. سجّل الدخول أعلاه لفتح وحدة الإدارة أو تطبيق الموظف للجوال وجرّب الموظفين والحضور والإجازات والرواتب والتوظيف والتقارير ببيانات تجريبية.","hr.h2.try":"ما الذي يمكنك تجربته","hr.f1.h":"الموظفون","hr.f1.p":"الملفات الشخصية والأقسام وأنواع التوظيف والمستندات في دليل واحد.","hr.f2.h":"الحضور","hr.f2.p":"الحضور اليومي وكشف شهري وتسجيل حضور الموظف بصورة شخصية وسياج جغرافي.","hr.f3.h":"الإجازات","hr.f3.p":"أنواع الإجازات والأرصدة والطلبات والموافقات وفق سياسة واضحة.","hr.f4.h":"الرواتب","hr.f4.p":"دورات رواتب شهرية تشمل الراتب الأساسي وبدل السكن وصندوق الادخار والتأمين وضريبة المهنة وضريبة الاستقطاع، مع قسائم الرواتب.","hr.f5.h":"التوظيف","hr.f5.p":"الوظائف الشاغرة ومسار المرشحين والمقابلات مع الملاحظات والعروض مع الإعداد للانضمام.","hr.f6.h":"التقارير","hr.f6.p":"اتجاهات الحضور وعدد الموظفين حسب القسم ومسار التوظيف ومخططات التكلفة.","hr.h2.admin":"وحدة الإدارة وتطبيق الموظف","hr.p2":"يدير مسؤولو الموارد البشرية الأشخاص ويوافقون على الإجازات ويشغّلون الرواتب ويقرؤون التقارير في الوحدة. ويستخدم الموظفون تطبيقًا بحجم الهاتف لتسجيل الحضور بصورة شخصية داخل السياج الجغرافي للمكتب وطلب الإجازة وعرض قسائم الرواتب.","hr.h2.demo":"حول البيانات التجريبية","hr.p3":"كل شيء يعمل في متصفحك ويستخدم بيانات تجريبية. تبقى التغييرات على جهازك. لا تُدخل معلومات حقيقية عن الموظفين أو الرواتب.","hr.l.speed":"اختبار سرعة الإنترنت"}'),
        ('about', N'{"about.h1":"About this site","about.p1":"thakurg.com is a small collection of free tools. The home page is an internet speed test that measures ping, jitter, download and upload speed. It works in English, Hindi and Arabic, and it can be installed on your phone or computer like an app.","about.p2":"Atrium HR is a demo workspace for employees, attendance, leave, payroll, hiring and reports. Creta is a simple audio player for tracks hosted on this site.","about.p3":"Everything runs in your browser. Settings, themes and saved speed test results stay on your device.","about.h2.tools":"What you can do here","about.l.speed":"Test your internet speed","about.l.hr":"Explore the Atrium HR demo","about.l.creta":"Listen with the Creta audio player","seo.about.title":"About thakurg.com","seo.about.desc":"About thakurg.com: a free internet speed test, the Atrium HR demo and the Creta audio player."}', N'{"about.h1":"इस साइट के बारे में","about.p1":"thakurg.com मुफ़्त टूल्स का एक छोटा संग्रह है। होम पेज एक इंटरनेट स्पीड टेस्ट है जो पिंग, जिटर, डाउनलोड और अपलोड स्पीड नापता है। यह अंग्रेज़ी, हिंदी और अरबी में चलता है, और इसे ऐप की तरह अपने फ़ोन या कंप्यूटर पर इंस्टॉल किया जा सकता है।","about.p2":"एट्रियम एचआर कर्मचारी, उपस्थिति, छुट्टी, पेरोल, भर्ती और रिपोर्ट के लिए एक डेमो वर्कस्पेस है। क्रेटा इस साइट पर रखे ट्रैक सुनने के लिए एक सरल ऑडियो प्लेयर है।","about.p3":"सब कुछ आपके ब्राउज़र में चलता है। सेटिंग, थीम और सेव किए गए स्पीड टेस्ट के नतीजे आपके डिवाइस पर ही रहते हैं।","about.h2.tools":"यहां आप क्या कर सकते हैं","about.l.speed":"अपनी इंटरनेट स्पीड जांचें","about.l.hr":"एट्रियम एचआर डेमो देखें","about.l.creta":"क्रेटा ऑडियो प्लेयर पर सुनें","seo.about.title":"thakurg.com के बारे में","seo.about.desc":"thakurg.com के बारे में: मुफ़्त इंटरनेट स्पीड टेस्ट, एट्रियम एचआर डेमो और क्रेटा ऑडियो प्लेयर।"}', N'{"about.h1":"عن هذا الموقع","about.p1":"thakurg.com مجموعة صغيرة من الأدوات المجانية. الصفحة الرئيسية هي اختبار لسرعة الإنترنت يقيس زمن الاستجابة والاهتزاز وسرعتي التنزيل والرفع. يعمل بالإنجليزية والهندية والعربية، ويمكن تثبيته على هاتفك أو حاسوبك مثل أي تطبيق.","about.p2":"أتريوم للموارد البشرية مساحة عمل تجريبية للموظفين والحضور والإجازات والرواتب والتوظيف والتقارير. أما كريتا فهو مشغل صوتي بسيط للمقاطع المستضافة على هذا الموقع.","about.p3":"كل شيء يعمل في متصفحك. تبقى الإعدادات والمظاهر ونتائج اختبار السرعة المحفوظة على جهازك.","about.h2.tools":"ماذا يمكنك أن تفعل هنا","about.l.speed":"اختبر سرعة الإنترنت لديك","about.l.hr":"جرّب النسخة التجريبية من أتريوم للموارد البشرية","about.l.creta":"استمع عبر مشغل كريتا الصوتي","seo.about.title":"عن thakurg.com","seo.about.desc":"عن thakurg.com: اختبار سرعة إنترنت مجاني، ونسخة أتريوم التجريبية للموارد البشرية، ومشغل كريتا الصوتي."}'),
        ('privacy', N'{"privacy.h1":"Privacy policy","privacy.p1":"This site does not ask you to sign up and does not collect personal information.","privacy.p2":"Your chosen language, theme and any speed test results you save are stored in your own browser (local storage). They are never sent to our servers and you can clear them at any time.","privacy.p3":"When you run a speed test, your browser connects to our own speed test server to move test data. Our server sees your IP address as part of that connection, as with any website request. The connection details and services status sections also contact ipwho.is, api4.ipify.org and api6.ipify.org (to show your IPv4 and IPv6 address) and the public status pages of the listed services. These requests go directly from your browser, and nothing is stored.","privacy.p4":"The site serves its own fonts. Only the Atrium HR demo loads fonts from Google Fonts, and Google may receive your IP address when you open it.","privacy.p5":"If this policy changes, the new version will be published on this page.","seo.privacy.title":"Privacy Policy","seo.privacy.desc":"How thakurg.com handles your data. No signup, no personal data collected, results stay in your browser."}', N'{"privacy.h1":"गोपनीयता नीति","privacy.p1":"यह साइट आपसे साइन अप नहीं करवाती और कोई व्यक्तिगत जानकारी इकट्ठा नहीं करती।","privacy.p2":"आपकी चुनी हुई भाषा, थीम और सेव किए गए स्पीड टेस्ट के नतीजे आपके अपने ब्राउज़र (लोकल स्टोरेज) में रखे जाते हैं। ये कभी हमारे सर्वर पर नहीं भेजे जाते और आप इन्हें कभी भी हटा सकते हैं।","privacy.p3":"जब आप स्पीड टेस्ट चलाते हैं, तो आपका ब्राउज़र टेस्ट डेटा भेजने-पाने के लिए हमारे अपने स्पीड टेस्ट सर्वर से जुड़ता है। किसी भी वेबसाइट अनुरोध की तरह, इस कनेक्शन में हमारा सर्वर आपका IP पता देख सकता है। कनेक्शन विवरण और सेवाओं की स्थिति वाले हिस्से ipwho.is, api4.ipify.org और api6.ipify.org (आपका IPv4 और IPv6 पता दिखाने के लिए) और सूचीबद्ध सेवाओं के सार्वजनिक स्टेटस पेज से भी जुड़ते हैं। ये अनुरोध सीधे आपके ब्राउज़र से जाते हैं और कुछ भी सहेजा नहीं जाता।","privacy.p4":"साइट अपने फ़ॉन्ट खुद उपलब्ध कराती है। सिर्फ़ एट्रियम एचआर डेमो Google Fonts से फ़ॉन्ट लोड करता है, और उसे खोलने पर Google को आपका IP पता मिल सकता है।","privacy.p5":"अगर यह नीति बदलती है, तो नया संस्करण इसी पेज पर प्रकाशित किया जाएगा।","seo.privacy.title":"गोपनीयता नीति","seo.privacy.desc":"thakurg.com आपके डेटा को कैसे संभालता है। साइन अप नहीं, कोई व्यक्तिगत डेटा नहीं, नतीजे आपके ब्राउज़र में रहते हैं।"}', N'{"privacy.h1":"سياسة الخصوصية","privacy.p1":"لا يطلب هذا الموقع منك التسجيل ولا يجمع أي معلومات شخصية.","privacy.p2":"تُحفظ اللغة والمظهر اللذان اخترتهما ونتائج اختبار السرعة التي تحفظها في متصفحك أنت (التخزين المحلي). لا تُرسل أبدًا إلى خوادمنا ويمكنك مسحها في أي وقت.","privacy.p3":"عند إجراء اختبار السرعة، يتصل متصفحك بخادم اختبار السرعة الخاص بنا لنقل بيانات الاختبار. قد يرى خادمنا عنوان IP الخاص بك ضمن هذا الاتصال، كما يحدث مع أي طلب إلى موقع ويب. كما يتصل قسما تفاصيل الاتصال وحالة الخدمات بالموقعين ipwho.is, api4.ipify.org وapi6.ipify.org (لعرض عنوان IPv4 وIPv6) وبصفحات الحالة العامة للخدمات المدرجة. تُرسل هذه الطلبات مباشرة من متصفحك ولا يتم تخزين أي شيء.","privacy.p4":"يقدّم الموقع خطوطه بنفسه. فقط النسخة التجريبية أتريوم للموارد البشرية تحمّل الخطوط من Google Fonts، وقد تتلقى Google عنوان IP الخاص بك عند فتحها.","privacy.p5":"إذا تغيّرت هذه السياسة، فستُنشر النسخة الجديدة في هذه الصفحة.","seo.privacy.title":"سياسة الخصوصية","seo.privacy.desc":"كيف يتعامل thakurg.com مع بياناتك. بلا تسجيل ولا جمع لبيانات شخصية، والنتائج تبقى في متصفحك."}'),
        ('terms', N'{"terms.h1":"Terms of use","terms.p1":"The tools on this site are provided free of charge, as they are, with no warranty of any kind.","terms.p2":"Speed test results are estimates. They depend on your device, network, browser and the distance to the test server, and they may differ from the speed your provider advertises.","terms.p3":"A full speed test transfers test data for about 25 seconds, which may count against a limited data plan. You are responsible for any data charges.","terms.p4":"Atrium HR is a demo that uses sample data. Do not enter real employee or payroll information.","terms.p5":"Please do not misuse the site, for example by trying to overload the test servers.","seo.terms.title":"Terms of Use","seo.terms.desc":"Terms of use for the free tools on thakurg.com."}', N'{"terms.h1":"उपयोग की शर्तें","terms.p1":"इस साइट के टूल्स मुफ़्त और \"जैसे हैं वैसे\" दिए जाते हैं, किसी भी तरह की वारंटी के बिना।","terms.p2":"स्पीड टेस्ट के नतीजे अनुमान हैं। ये आपके डिवाइस, नेटवर्क, ब्राउज़र और टेस्ट सर्वर की दूरी पर निर्भर करते हैं, और प्रोवाइडर की बताई स्पीड से अलग हो सकते हैं।","terms.p3":"पूरा स्पीड टेस्ट लगभग 25 सेकंड तक टेस्ट डेटा ट्रांसफ़र करता है, जो सीमित डेटा प्लान में गिना जा सकता है। डेटा के किसी भी शुल्क की ज़िम्मेदारी आपकी है।","terms.p4":"एट्रियम एचआर एक डेमो है जो नमूना डेटा इस्तेमाल करता है। असली कर्मचारी या पेरोल जानकारी न डालें।","terms.p5":"कृपया साइट का दुरुपयोग न करें, जैसे टेस्ट सर्वर पर ज़्यादा बोझ डालने की कोशिश।","seo.terms.title":"उपयोग की शर्तें","seo.terms.desc":"thakurg.com के मुफ़्त टूल्स के उपयोग की शर्तें।"}', N'{"terms.h1":"شروط الاستخدام","terms.p1":"الأدوات في هذا الموقع مقدمة مجانًا وكما هي، دون أي ضمان من أي نوع.","terms.p2":"نتائج اختبار السرعة تقديرية. وهي تعتمد على جهازك وشبكتك ومتصفحك وبُعدك عن خادم الاختبار، وقد تختلف عن السرعة التي يعلنها مزوّد الخدمة.","terms.p3":"ينقل اختبار السرعة الكامل بيانات اختبارية لمدة 25 ثانية تقريبًا، وقد تُحتسب من باقة بيانات محدودة. أنت مسؤول عن أي رسوم بيانات.","terms.p4":"أتريوم للموارد البشرية نسخة تجريبية تستخدم بيانات نموذجية. لا تُدخل معلومات حقيقية عن موظفين أو رواتب.","terms.p5":"يرجى عدم إساءة استخدام الموقع، مثل محاولة إرهاق خوادم الاختبار.","seo.terms.title":"شروط الاستخدام","seo.terms.desc":"شروط استخدام الأدوات المجانية في thakurg.com."}'),
        ('notfound', N'{"nf.h1":"Page not found","nf.p":"The page you are looking for does not exist or has moved.","nf.home":"Go to the speed test","err.h1":"Something went wrong","err.p":"That action could not be completed. Please go back and try again.","err.home":"Back to home","offpage.h1":"You are offline","offpage.p":"This page needs an internet connection. Check your connection, then try again. The speed test and your saved results stay available.","seo.offline.title":"You are offline","seo.offline.desc":"You are offline. Check your internet connection and try again.","seo.404.title":"Page not found","seo.404.desc":"The page you are looking for does not exist.","seo.error.title":"Something went wrong","seo.error.desc":"That action could not be completed."}', N'{"nf.h1":"पेज नहीं मिला","nf.p":"आप जो पेज ढूंढ रहे हैं वह मौजूद नहीं है या हट गया है।","nf.home":"स्पीड टेस्ट पर जाएं","err.h1":"कुछ गड़बड़ हो गई","err.p":"यह कार्रवाई पूरी नहीं हो सकी। कृपया वापस जाकर फिर कोशिश करें।","err.home":"होम पर वापस जाएं","offpage.h1":"आप ऑफ़लाइन हैं","offpage.p":"इस पेज के लिए इंटरनेट कनेक्शन चाहिए। अपना कनेक्शन जांचें और फिर कोशिश करें। स्पीड टेस्ट और आपके सेव किए नतीजे उपलब्ध रहेंगे।","seo.offline.title":"आप ऑफ़लाइन हैं","seo.offline.desc":"आप ऑफ़लाइन हैं। अपना इंटरनेट कनेक्शन जांचें और फिर कोशिश करें।","seo.404.title":"पेज नहीं मिला","seo.404.desc":"आप जो पेज ढूंढ रहे हैं वह मौजूद नहीं है।","seo.error.title":"कुछ गड़बड़ हो गई","seo.error.desc":"यह कार्रवाई पूरी नहीं हो सकी।"}', N'{"nf.h1":"الصفحة غير موجودة","nf.p":"الصفحة التي تبحث عنها غير موجودة أو تم نقلها.","nf.home":"انتقل إلى اختبار السرعة","err.h1":"حدث خطأ ما","err.p":"تعذّر إكمال هذا الإجراء. يرجى الرجوع والمحاولة مرة أخرى.","err.home":"العودة إلى الرئيسية","offpage.h1":"أنت غير متصل","offpage.p":"تحتاج هذه الصفحة إلى اتصال بالإنترنت. تحقق من اتصالك ثم حاول مرة أخرى. يبقى اختبار السرعة ونتائجك المحفوظة متاحة.","seo.offline.title":"أنت غير متصل","seo.offline.desc":"أنت غير متصل. تحقق من اتصالك بالإنترنت وحاول مرة أخرى.","seo.404.title":"الصفحة غير موجودة","seo.404.desc":"الصفحة التي تبحث عنها غير موجودة.","seo.error.title":"حدث خطأ ما","seo.error.desc":"تعذّر إكمال هذا الإجراء."}'),
        ('config', N'{"cfg.h1":"Settings","cfg.lead":"Choose a tab. The tabs you see depend on the rights of your role.","cfg.note":"Site option changes preview only in this browser until you press Save. Saving applies to every visitor.","cfg.changed":"{n} unsaved change(s).","cfg.nochange":"Everything matches the saved settings.","cfg.reset":"Discard changes","cfg.on":"On","cfg.off":"Off","cfg.default":"Default: {value}","cfg.conn.h":"Your connection details","cfg.conn.all":"Show the whole section","cfg.svc.h":"Services status","cfg.svc.all":"Show the whole section","cfg.yt.h":"YouTube API key","cfg.yt.lead":"Optional. With a key, YouTube search, playlists and video details use the official YouTube Data API; without one the player still works. The key is checked with YouTube and stored in the database. It is never shown again.","cfg.yt.label":"YouTube Data API v3 key","cfg.yt.save":"Save key","cfg.yt.saving":"Checking...","cfg.yt.set":"A YouTube API key is saved.","cfg.yt.notset":"No YouTube API key is saved yet.","cfg.gauge":"Speed gauge: speeds shown on the meter (Mbps, separated by commas)","cfg.gauge.help":"Evenly spaced around the meter, for example 0, 5, 10, 25, 100, 1000. The first must be 0, each larger than the one before (2 to 20 values, up to 100000). 1000 and above show as Gbps.","cfg.gauge.bad":"Not saved to the draft: use 2 to 20 whole numbers, starting at 0, each larger than the one before, up to 100000.","cfg.svc.refresh":"Re-check every (seconds, 0 = never)","cfg.json.h":"Export and import","cfg.json.help":"Copy this JSON to keep or share your settings. Paste JSON and press Import to load it as unsaved changes.","cfg.json.import":"Import","cfg.json.ok":"Imported.","cfg.json.bad":"That is not valid settings JSON.","seo.cfg.title":"Settings: turn site features on or off","seo.cfg.desc":"Switch pages, players, downloads and other features of thakurg.com on or off and see the site update.","cfg.save":"Save","cfg.save.all":"Save all changes","cfg.save.saving":"Saving…","cfg.save.nothing":"Nothing to save.","cfg.admin.p":"Your role has no settings to show. Ask an administrator for access.","cfg.admin.cta":"Go to your profile","cfg.users.h":"Users and access","cfg.users.lead":"Tick the apps each account may open, then press Save on that row. Administrators can open every app and change these settings.","cfg.users.auto":"Given to every new account: {apps}.","cfg.users.you":"(you)","cfg.users.admin":"Administrator","cfg.users.apps":"Access of {name}","cfg.users.loading":"Loading users…","cfg.tabs":"Settings sections","cfg.loading":"Loading…","cfg.readonly":"Your role can view this but not change it.","perm.page.settings.account":"For me","perm.page.settings.users":"Users","perm.page.settings.roles":"Roles","perm.page.settings.permissions":"Role rights","perm.page.settings.features":"Site options","perm.page.settings.connection":"Connection details","perm.page.settings.services":"Services status","perm.page.settings.youtube":"YouTube key","perm.page.settings.json":"Import and export","acc.look.h":"Language and skin","acc.look.help":"The language is saved with your account; light or dark and the style are kept in this browser.","acc.own.h":"My page options","acc.own.help":"Switch off the parts of your own pages you do not want to see. A switch saves at once and changes only what you see.","acc.own.siteOff":"Switched off for the whole site by an administrator.","acc.own.none":"There are no options for your pages here.","usr.h":"Users","usr.lead":"Add users with a role and their apps. Tap the pencil to change a user, the cross to delete one. Administrators can open every app.","usr.add.h":"Add a user","usr.add.btn":"Add user","usr.role":"Role","usr.role.default":"{name} (sign-up)","usr.apps":"Apps","usr.locked":"Only a super admin can change a super admin.","usr.self":"You cannot change your own role.","usr.delete":"Delete","usr.delete.sure":"Press again to delete","role.h":"Roles","role.lead":"Add, rename and delete role